"""Exception hierarchy for microdb."""


class MicroDBError(Exception):
    """Base error for all microdb failures."""


class LexError(MicroDBError):
    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset = offset


class ParseError(MicroDBError):
    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset = offset


class SchemaError(MicroDBError):
    """Invalid table schema or row payload."""


class TypeMismatchError(MicroDBError):
    """Value has the wrong type for an operation."""


class UnknownColumnError(MicroDBError):
    """Column name could not be resolved."""


class AmbiguousColumnError(MicroDBError):
    """Column name matches more than one column."""


class UnknownTableError(MicroDBError):
    """Table name is not in scope."""


class UnknownFunctionError(MicroDBError):
    """Scalar or aggregate function does not exist."""


class ArityError(MicroDBError):
    def __init__(self, name: str, expected: int, got: int) -> None:
        super().__init__(f"{name} expected {expected} argument(s), got {got}")
        self.name = name
        self.expected = expected
        self.got = got


class AggregateError(MicroDBError):
    """Aggregate used in a context that forbids it."""


class GroupingError(MicroDBError):
    """SELECT item is illegal under GROUP BY rules."""

"""Value model, three-valued logic, comparison, and arithmetic."""

from __future__ import annotations

from microdb.errors import TypeMismatchError


def type_of(v: object) -> str:
    if v is None:
        return "NULL"
    if v is True or v is False:
        return "BOOL"
    if isinstance(v, int) and not isinstance(v, bool):
        return "INT"
    if isinstance(v, float):
        return "FLOAT"
    if isinstance(v, str):
        return "TEXT"
    raise TypeMismatchError(f"unsupported value {v!r}")


def is_numeric(v: object) -> bool:
    return type_of(v) in ("INT", "FLOAT")


def and_(a: bool | None, b: bool | None) -> bool | None:
    _check_logical(a)
    _check_logical(b)
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or_(a: bool | None, b: bool | None) -> bool | None:
    _check_logical(a)
    _check_logical(b)
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not_(a: bool | None) -> bool | None:
    _check_logical(a)
    if a is None:
        return None
    return not a


def compare_eq(a: object, b: object) -> bool | None:
    if a is None or b is None:
        return None
    ta, tb = type_of(a), type_of(b)
    if _numeric_pair(ta, tb):
        return a == b
    if ta == tb == "TEXT":
        return a == b
    if ta == tb == "BOOL":
        return a is b
    raise TypeMismatchError(f"cannot compare {ta} and {tb}")


def compare_lt(a: object, b: object) -> bool | None:
    if a is None or b is None:
        return None
    ta, tb = type_of(a), type_of(b)
    if _numeric_pair(ta, tb):
        return bool(a < b)  # type: ignore[operator]
    if ta == tb == "TEXT":
        return bool(a < b)  # type: ignore[operator]
    if ta == tb == "BOOL":
        return (not a) and b
    raise TypeMismatchError(f"cannot compare {ta} and {tb}")


def compare_ne(a: object, b: object) -> bool | None:
    return not_(compare_eq(a, b))


def compare_le(a: object, b: object) -> bool | None:
    return or_(compare_lt(a, b), compare_eq(a, b))


def compare_gt(a: object, b: object) -> bool | None:
    return compare_lt(b, a)


def compare_ge(a: object, b: object) -> bool | None:
    return or_(compare_lt(b, a), compare_eq(a, b))


def arith(op: str, a: object, b: object) -> object:
    if a is None or b is None:
        return None
    if not is_numeric(a) or not is_numeric(b):
        raise TypeMismatchError(f"arithmetic on {type_of(a)} and {type_of(b)}")
    if op == "+":
        return _num_result(a, b, a + b)  # type: ignore[operator]
    if op == "-":
        return _num_result(a, b, a - b)  # type: ignore[operator]
    if op == "*":
        return _num_result(a, b, a * b)  # type: ignore[operator]
    if op == "/":
        return _div(a, b)
    if op == "%":
        return _mod(a, b)
    raise TypeMismatchError(f"unknown arithmetic operator {op}")


def negate(a: object) -> object:
    if a is None:
        return None
    if not is_numeric(a):
        raise TypeMismatchError(f"cannot negate {type_of(a)}")
    return -a  # type: ignore[operator]


def as_logical(v: object) -> bool | None:
    if v is True or v is False or v is None:
        return v
    raise TypeMismatchError(f"expected BOOL, got {type_of(v)}")


def group_canon(v: object) -> tuple[object, ...]:
    if v is None:
        return ("NULL",)
    kind = type_of(v)
    if kind == "INT":
        return ("NUM", float(v))  # type: ignore[arg-type]
    if kind == "FLOAT":
        return ("NUM", v)
    if kind == "BOOL":
        return ("BOOL", v)
    return ("TEXT", v)


def distinct_canon(v: object) -> tuple[object, ...]:
    if v is None:
        return ("NULL",)
    return (type_of(v), v)


def _check_logical(v: bool | None) -> None:
    if v is not True and v is not False and v is not None:
        raise TypeMismatchError("logical operand must be BOOL or NULL")


def _numeric_pair(ta: str, tb: str) -> bool:
    return ta in ("INT", "FLOAT") and tb in ("INT", "FLOAT")


def _num_result(a: object, b: object, result: object) -> object:
    if type_of(a) == "INT" and type_of(b) == "INT":
        return int(result)  # type: ignore[arg-type]
    return float(result)  # type: ignore[arg-type]


def _div(a: object, b: object) -> object:
    bf = float(b)  # type: ignore[arg-type]
    if bf == 0.0:
        return None
    return float(a) / bf  # type: ignore[arg-type]


def _mod(a: object, b: object) -> object:
    if type_of(a) != "INT" or type_of(b) != "INT":
        raise TypeMismatchError("% requires INT operands")
    if b == 0:
        return None
    return a % b  # type: ignore[operator]

"""Column and Table schema objects."""

from __future__ import annotations

import dataclasses

from microdb.errors import SchemaError

_TYPES = frozenset({"INT", "FLOAT", "TEXT", "BOOL"})


@dataclasses.dataclass(frozen=True)
class Column:
    name: str
    type: str


class Table:
    def __init__(
        self, name: str, columns: list[Column], rows: list[list[object]]
    ) -> None:
        if not columns:
            raise SchemaError("table must have at least one column")
        seen: set[str] = set()
        for col in columns:
            if col.name in seen:
                raise SchemaError(f"duplicate column {col.name!r}")
            seen.add(col.name)
            if col.type not in _TYPES:
                raise SchemaError(f"invalid column type {col.type!r}")
        width = len(columns)
        stored: list[list[object]] = []
        for row in rows:
            if len(row) != width:
                raise SchemaError("row width does not match column count")
            stored.append([_coerce(columns[i], row[i]) for i in range(width)])
        self._name = name
        self._columns = list(columns)
        self._rows = stored

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return self._columns

    @property
    def rows(self) -> list[list[object]]:
        return self._rows

    def column_index(self, name: str) -> int:
        for i, col in enumerate(self._columns):
            if col.name == name:
                return i
        raise SchemaError(f"unknown column {name!r}")


def _coerce(col: Column, value: object) -> object:
    if value is None:
        return None
    if col.type == "INT":
        if isinstance(value, int) and not isinstance(value, bool):
            return value
        raise SchemaError(f"expected INT for {col.name!r}")
    if col.type == "FLOAT":
        if isinstance(value, bool):
            raise SchemaError(f"expected FLOAT for {col.name!r}")
        if isinstance(value, float):
            return value
        if isinstance(value, int):
            return float(value)
        raise SchemaError(f"expected FLOAT for {col.name!r}")
    if col.type == "TEXT":
        if isinstance(value, str):
            return value
        raise SchemaError(f"expected TEXT for {col.name!r}")
    if value is True or value is False:
        return value
    raise SchemaError(f"expected BOOL for {col.name!r}")

"""Recursive-descent parser for the microdb query language."""

from __future__ import annotations

import dataclasses

from microdb.errors import ParseError
from microdb.lexer import Token, tokenize

_AGGS = frozenset({"count", "sum", "avg", "min", "max"})
_CMP = frozenset({"=", "<>", "<", "<=", ">", ">="})
_CLAUSE = frozenset(
    {
        "FROM",
        "WHERE",
        "GROUP",
        "HAVING",
        "ORDER",
        "LIMIT",
        "OFFSET",
        "INNER",
        "LEFT",
        "JOIN",
        "EOF",
    }
)


@dataclasses.dataclass(frozen=True)
class Literal:
    value: object
    offset: int
    source: str


@dataclasses.dataclass(frozen=True)
class ColumnRef:
    name: str
    table: str | None
    offset: int
    source: str


@dataclasses.dataclass(frozen=True)
class Binary:
    op: str
    left: object
    right: object
    offset: int
    source: str


@dataclasses.dataclass(frozen=True)
class Unary:
    op: str
    expr: object
    offset: int
    source: str


@dataclasses.dataclass(frozen=True)
class IsNull:
    expr: object
    negated: bool
    offset: int
    source: str


@dataclasses.dataclass(frozen=True)
class Call:
    name: str
    args: tuple[object, ...]
    star: bool
    offset: int
    source: str


@dataclasses.dataclass(frozen=True)
class Star:
    table: str | None
    offset: int
    source: str


@dataclasses.dataclass(frozen=True)
class SelectItem:
    value: object
    alias: str | None


@dataclasses.dataclass(frozen=True)
class JoinClause:
    kind: str
    table: str
    on: object


@dataclasses.dataclass(frozen=True)
class OrderItem:
    expr: object
    desc: bool


@dataclasses.dataclass(frozen=True)
class Query:
    distinct: bool
    select_items: list[SelectItem]
    from_table: str
    join: JoinClause | None
    where: object | None
    group_by: list[object]
    having: object | None
    order_by: list[OrderItem]
    limit: int | None
    offset: int | None


def parse(source: str) -> Query:
    return Parser(source).parse_query()


def collapse_ws(text: str) -> str:
    return " ".join(text.split())


class Parser:
    def __init__(self, source: str) -> None:
        self.source = source
        self.tokens = tokenize(source)
        self.i = 0
        self._end = 0
        self._agg_depth = 0

    def parse_query(self) -> Query:
        self._expect("SELECT")
        distinct = self._match("DISTINCT")
        items = self._select_list()
        self._expect("FROM")
        table = self._expect_ident()
        join = self._parse_join()
        where = self._parse_or() if self._match("WHERE") else None
        group_by = self._group_by()
        having = self._parse_or() if self._match("HAVING") else None
        order_by = self._order_by()
        limit = self._int_clause("LIMIT")
        offset = self._int_clause("OFFSET")
        if self._peek().kind != "EOF":
            raise ParseError("unexpected input after query", self._peek().offset)
        return Query(
            distinct, items, table, join, where, group_by, having, order_by, limit, offset
        )

    def _parse_join(self) -> JoinClause | None:
        if self._peek().kind not in ("INNER", "LEFT"):
            return None
        kind = self._peek().kind
        self._advance()
        self._expect("JOIN")
        table = self._expect_ident()
        self._expect("ON")
        return JoinClause(kind, table, self._parse_or())

    def _group_by(self) -> list[object]:
        if not self._match("GROUP"):
            return []
        self._expect("BY")
        return self._expr_list()

    def _order_by(self) -> list[OrderItem]:
        if not self._match("ORDER"):
            return []
        self._expect("BY")
        items = [self._order_item()]
        while self._match(","):
            items.append(self._order_item())
        return items

    def _order_item(self) -> OrderItem:
        expr = self._parse_or()
        desc = False
        if self._match("DESC"):
            desc = True
        else:
            self._match("ASC")
        return OrderItem(expr, desc)

    def _int_clause(self, kind: str) -> int | None:
        if not self._match(kind):
            return None
        tok = self._peek()
        if tok.kind != "INT":
            raise ParseError(f"{kind} requires an integer", tok.offset)
        self._advance()
        return int(tok.value)  # type: ignore[arg-type]

    def _select_list(self) -> list[SelectItem]:
        items = [self._select_item()]
        while self._match(","):
            items.append(self._select_item())
        return items

    def _select_item(self) -> SelectItem:
        tok = self._peek()
        if tok.kind == "*":
            self._advance()
            return SelectItem(Star(None, tok.offset, "*"), None)
        if self._is_qualified_star():
            table = self._expect_ident()
            self._advance()
            star = self._peek()
            self._advance()
            src = collapse_ws(self.source[tok.offset : self._end])
            return SelectItem(Star(table, tok.offset, src), None)
        expr = self._parse_or()
        alias = self._expect_ident() if self._match("AS") else None
        return SelectItem(expr, alias)

    def _is_qualified_star(self) -> bool:
        if self._peek().kind != "IDENT":
            return False
        if self._ahead(1).kind != ".":
            return False
        return self._ahead(2).kind == "*"

    def _expr_list(self) -> list[object]:
        items = [self._parse_or()]
        while self._match(","):
            items.append(self._parse_or())
        return items

    def _parse_or(self) -> object:
        start = self._peek().offset
        left = self._parse_and()
        while self._match("OR"):
            right = self._parse_and()
            left = Binary("OR", left, right, start, self._src(start))
        return left

    def _parse_and(self) -> object:
        start = self._peek().offset
        left = self._parse_not()
        while self._match("AND"):
            right = self._parse_not()
            left = Binary("AND", left, right, start, self._src(start))
        return left

    def _parse_not(self) -> object:
        if self._match("NOT"):
            start = self._end - 3
            expr = self._parse_not()
            return Unary("NOT", expr, start, self._src(start))
        return self._parse_predicate()

    def _parse_predicate(self) -> object:
        start = self._peek().offset
        left = self._parse_additive()
        if self._match("IS"):
            return self._finish_is_null(left, start)
        tok = self._peek()
        if tok.kind in _CMP:
            self._advance()
            right = self._parse_additive()
            node: object = Binary(tok.kind, left, right, start, self._src(start))
            if self._peek().kind in _CMP or self._peek().kind == "IS":
                raise ParseError("predicate is not associative", self._peek().offset)
            return node
        return left

    def _finish_is_null(self, left: object, start: int) -> IsNull:
        negated = self._match("NOT")
        self._expect("NULL")
        return IsNull(left, negated, start, self._src(start))

    def _parse_additive(self) -> object:
        start = self._peek().offset
        left = self._parse_multiplicative()
        while self._peek().kind in ("+", "-"):
            op = self._peek().kind
            self._advance()
            right = self._parse_multiplicative()
            left = Binary(op, left, right, start, self._src(start))
        return left

    def _parse_multiplicative(self) -> object:
        start = self._peek().offset
        left = self._parse_unary()
        while self._peek().kind in ("*", "/", "%"):
            op = self._peek().kind
            self._advance()
            right = self._parse_unary()
            left = Binary(op, left, right, start, self._src(start))
        return left

    def _parse_unary(self) -> object:
        if self._match("-"):
            start = self._end - 1
            expr = self._parse_unary()
            return Unary("-", expr, start, self._src(start))
        return self._parse_primary()

    def _parse_primary(self) -> object:
        tok = self._peek()
        if tok.kind in ("INT", "FLOAT", "TEXT", "TRUE", "FALSE", "NULL"):
            self._advance()
            return Literal(tok.value, tok.offset, tok.text)
        if tok.kind == "(":
            self._advance()
            expr = self._parse_or()
            self._expect(")")
            return expr
        if tok.kind == "IDENT":
            return self._parse_ident_primary()
        raise ParseError("expected expression", tok.offset)

    def _parse_ident_primary(self) -> object:
        tok = self._peek()
        name = self._expect_ident()
        if self._match("("):
            return self._parse_call(name, tok.offset)
        table = None
        col = name
        if self._match("."):
            table = name
            col = self._expect_ident()
        src = collapse_ws(self.source[tok.offset : self._end])
        return ColumnRef(col, table, tok.offset, src)

    def _parse_call(self, name: str, start: int) -> Call:
        lower = name.lower()
        nested = lower in _AGGS
        if nested:
            if self._agg_depth:
                raise ParseError("nested aggregate", start)
            self._agg_depth += 1
        try:
            args, star = self._parse_args(lower)
        finally:
            if nested:
                self._agg_depth -= 1
        return Call(lower, tuple(args), star, start, self._src(start))

    def _parse_args(self, name: str) -> tuple[list[object], bool]:
        if name == "count" and self._match("*"):
            self._expect(")")
            return [], True
        if self._match(")"):
            return [], False
        args = [self._parse_or()]
        while self._match(","):
            args.append(self._parse_or())
        self._expect(")")
        return args, False

    def _src(self, start: int) -> str:
        return collapse_ws(self.source[start : self._end])

    def _peek(self) -> Token:
        return self.tokens[self.i]

    def _ahead(self, n: int) -> Token:
        j = self.i + n
        if j >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[j]

    def _advance(self) -> Token:
        tok = self.tokens[self.i]
        if tok.kind != "EOF":
            self.i += 1
        self._end = tok.offset + len(tok.text)
        return tok

    def _match(self, kind: str) -> bool:
        if self._peek().kind == kind:
            self._advance()
            return True
        return False

    def _expect(self, kind: str) -> Token:
        tok = self._peek()
        if tok.kind != kind:
            raise ParseError(f"expected {kind}", tok.offset)
        return self._advance()

    def _expect_ident(self) -> str:
        tok = self._peek()
        if tok.kind != "IDENT":
            raise ParseError("expected identifier", tok.offset)
        self._advance()
        return str(tok.value)

"""Expression evaluation, binding, and tree walks."""

from __future__ import annotations

from dataclasses import dataclass

from microdb.errors import (
    AmbiguousColumnError,
    ArityError,
    AggregateError,
    TypeMismatchError,
    UnknownColumnError,
    UnknownFunctionError,
    UnknownTableError,
)
from microdb.parser import Binary, Call, ColumnRef, IsNull, Literal, Unary
from microdb.value import (
    and_,
    arith,
    as_logical,
    compare_eq,
    compare_ge,
    compare_gt,
    compare_le,
    compare_lt,
    compare_ne,
    is_numeric,
    negate,
    not_,
    or_,
    type_of,
)

AGGS = frozenset({"count", "sum", "avg", "min", "max"})
_CMP = {
    "=": compare_eq,
    "<>": compare_ne,
    "<": compare_lt,
    "<=": compare_le,
    ">": compare_gt,
    ">=": compare_ge,
}
_ARITY: dict[str, tuple[int, int | None]] = {
    "upper": (1, 1),
    "lower": (1, 1),
    "length": (1, 1),
    "abs": (1, 1),
    "concat": (2, None),
    "coalesce": (1, None),
    "count": (1, 1),
    "sum": (1, 1),
    "avg": (1, 1),
    "min": (1, 1),
    "max": (1, 1),
}


@dataclass
class EvalCtx:
    col_tables: list[str]
    col_names: list[str]
    row: list[object]
    aliases: dict[str, object] | None = None
    aggs: dict[int, object] | None = None
    allow_input: bool = True


def eval_expr(node: object, ctx: EvalCtx) -> object:
    if isinstance(node, Literal):
        return node.value
    if isinstance(node, ColumnRef):
        return _eval_column(node, ctx)
    if isinstance(node, Unary):
        return _eval_unary(node, ctx)
    if isinstance(node, Binary):
        return _eval_binary(node, ctx)
    if isinstance(node, IsNull):
        v = eval_expr(node.expr, ctx)
        isn = v is None
        return (not isn) if node.negated else isn
    if isinstance(node, Call):
        return _eval_call(node, ctx)
    raise TypeMismatchError("invalid expression node")


def has_aggregate(node: object) -> bool:
    found: list[Call] = []
    collect_aggregates(node, found)
    return bool(found)


def collect_aggregates(node: object, out: list[Call]) -> None:
    if isinstance(node, Call) and node.name in AGGS:
        out.append(node)
        return
    if isinstance(node, Unary):
        collect_aggregates(node.expr, out)
    elif isinstance(node, Binary):
        collect_aggregates(node.left, out)
        collect_aggregates(node.right, out)
    elif isinstance(node, IsNull):
        collect_aggregates(node.expr, out)
    elif isinstance(node, Call):
        for arg in node.args:
            collect_aggregates(arg, out)


def walk_children(node: object) -> list[object]:
    if isinstance(node, Unary):
        return [node.expr]
    if isinstance(node, Binary):
        return [node.left, node.right]
    if isinstance(node, IsNull):
        return [node.expr]
    if isinstance(node, Call):
        return list(node.args)
    return []


def bind_expr(node: object, col_tables: list[str], col_names: list[str]) -> object:
    if isinstance(node, ColumnRef):
        idx = resolve_column(col_tables, col_names, node.table, node.name)
        table = col_tables[idx]
        name = col_names[idx]
        return ColumnRef(name, table, node.offset, node.source)
    if isinstance(node, Unary):
        return Unary(node.op, bind_expr(node.expr, col_tables, col_names), node.offset, node.source)
    if isinstance(node, Binary):
        return Binary(
            node.op,
            bind_expr(node.left, col_tables, col_names),
            bind_expr(node.right, col_tables, col_names),
            node.offset,
            node.source,
        )
    if isinstance(node, IsNull):
        return IsNull(
            bind_expr(node.expr, col_tables, col_names), node.negated, node.offset, node.source
        )
    if isinstance(node, Call):
        args = tuple(bind_expr(a, col_tables, col_names) for a in node.args)
        return Call(node.name, args, node.star, node.offset, node.source)
    return node


def expr_equal(a: object, b: object) -> bool:
    if type(a) is not type(b):
        return False
    if isinstance(a, Literal) and isinstance(b, Literal):
        return type_of(a.value) == type_of(b.value) and a.value == b.value
    if isinstance(a, ColumnRef) and isinstance(b, ColumnRef):
        return a.name == b.name and a.table == b.table
    if isinstance(a, Unary) and isinstance(b, Unary):
        return a.op == b.op and expr_equal(a.expr, b.expr)
    if isinstance(a, Binary) and isinstance(b, Binary):
        return a.op == b.op and expr_equal(a.left, b.left) and expr_equal(a.right, b.right)
    if isinstance(a, IsNull) and isinstance(b, IsNull):
        return a.negated == b.negated and expr_equal(a.expr, b.expr)
    if isinstance(a, Call) and isinstance(b, Call):
        if a.name != b.name or a.star != b.star or len(a.args) != len(b.args):
            return False
        return all(expr_equal(x, y) for x, y in zip(a.args, b.args))
    return False


def resolve_column(
    col_tables: list[str], col_names: list[str], table: str | None, name: str
) -> int:
    tables = {t for t in col_tables}
    if table is not None:
        if table not in tables:
            raise UnknownTableError(table)
        hits = [i for i, (t, n) in enumerate(zip(col_tables, col_names)) if t == table and n == name]
        if not hits:
            raise UnknownColumnError(f"{table}.{name}")
        if len(hits) > 1:
            raise AmbiguousColumnError(f"{table}.{name}")
        return hits[0]
    hits = [i for i, n in enumerate(col_names) if n == name]
    if not hits:
        raise UnknownColumnError(name)
    owners = {col_tables[i] for i in hits}
    if len(owners) > 1 or len(hits) > 1:
        raise AmbiguousColumnError(name)
    return hits[0]


def eval_predicate(node: object, ctx: EvalCtx) -> bool | None:
    return as_logical(eval_expr(node, ctx))


def item_source(node: object) -> str:
    if isinstance(node, (Literal, ColumnRef, Binary, Unary, IsNull, Call)):
        return node.source
    return ""


def _eval_column(node: ColumnRef, ctx: EvalCtx) -> object:
    if node.table is None and ctx.aliases is not None and node.name in ctx.aliases:
        return ctx.aliases[node.name]
    if not ctx.allow_input:
        if node.table is not None:
            raise UnknownTableError(node.table)
        raise UnknownColumnError(node.name)
    idx = resolve_column(ctx.col_tables, ctx.col_names, node.table, node.name)
    return ctx.row[idx]


def _eval_unary(node: Unary, ctx: EvalCtx) -> object:
    inner = eval_expr(node.expr, ctx)
    if node.op == "NOT":
        return not_(as_logical(inner))
    return negate(inner)


def _eval_binary(node: Binary, ctx: EvalCtx) -> object:
    if node.op == "AND":
        return and_(as_logical(eval_expr(node.left, ctx)), as_logical(eval_expr(node.right, ctx)))
    if node.op == "OR":
        return or_(as_logical(eval_expr(node.left, ctx)), as_logical(eval_expr(node.right, ctx)))
    if node.op in _CMP:
        return _CMP[node.op](eval_expr(node.left, ctx), eval_expr(node.right, ctx))
    return arith(node.op, eval_expr(node.left, ctx), eval_expr(node.right, ctx))


def _eval_call(node: Call, ctx: EvalCtx) -> object:
    if node.name in AGGS:
        if ctx.aggs is not None and id(node) in ctx.aggs:
            return ctx.aggs[id(node)]
        raise AggregateError(f"aggregate {node.name} not allowed here")
    if node.name not in _ARITY:
        raise UnknownFunctionError(node.name)
    _check_arity(node.name, len(node.args), star=False)
    args = [eval_expr(a, ctx) for a in node.args]
    return _scalar(node.name, args)


def _check_arity(name: str, got: int, star: bool) -> None:
    if name == "count" and star:
        return
    lo, hi = _ARITY[name]
    if got < lo or (hi is not None and got > hi):
        raise ArityError(name, lo if hi is None or got < lo else hi, got)


def _scalar(name: str, args: list[object]) -> object:
    if name == "coalesce":
        for v in args:
            if v is not None:
                return v
        return None
    if name == "concat":
        return _concat(args)
    if any(v is None for v in args):
        return None
    if name == "upper":
        return _need_text(args[0]).upper()
    if name == "lower":
        return _need_text(args[0]).lower()
    if name == "length":
        return len(_need_text(args[0]))
    if name == "abs":
        if not is_numeric(args[0]):
            raise TypeMismatchError("abs requires numeric")
        return abs(args[0])  # type: ignore[arg-type]
    raise UnknownFunctionError(name)


def _concat(args: list[object]) -> object:
    texts: list[str] = []
    for v in args:
        if v is None:
            return None
        texts.append(_need_text(v))
    return "".join(texts)


def _need_text(v: object) -> str:
    if type_of(v) != "TEXT":
        raise TypeMismatchError(f"expected TEXT, got {type_of(v)}")
    return str(v)

"""Aggregate functions: count, sum, avg, min, max."""

from __future__ import annotations

from microdb.errors import TypeMismatchError
from microdb.expr import _check_arity
from microdb.parser import Call
from microdb.value import compare_lt, is_numeric, type_of


def eval_aggregate(call: Call, values: list[object]) -> object:
    if call.star:
        if call.name != "count":
            raise TypeMismatchError("* is only valid in count(*)")
        return len(values)
    _check_arity(call.name, 1, star=False)
    if call.name == "count":
        return sum(1 for v in values if v is not None)
    nonempty = [v for v in values if v is not None]
    if not nonempty:
        return None
    if call.name == "sum":
        return _sum(nonempty)
    if call.name == "avg":
        return _avg(nonempty)
    if call.name == "min":
        return _minmax(nonempty, take_lt=True)
    if call.name == "max":
        return _minmax(nonempty, take_lt=False)
    raise TypeMismatchError(f"unknown aggregate {call.name}")


def _sum(vals: list[object]) -> object:
    total: object = 0
    all_int = True
    for v in vals:
        if not is_numeric(v):
            raise TypeMismatchError("sum requires numeric input")
        if type_of(v) != "INT":
            all_int = False
        total = total + v  # type: ignore[operator]
    if all_int:
        return int(total)  # type: ignore[arg-type]
    return float(total)  # type: ignore[arg-type]


def _avg(vals: list[object]) -> object:
    total = 0.0
    for v in vals:
        if not is_numeric(v):
            raise TypeMismatchError("avg requires numeric input")
        total += float(v)  # type: ignore[arg-type]
    return total / len(vals)


def _minmax(vals: list[object], take_lt: bool) -> object:
    best = vals[0]
    for v in vals[1:]:
        less = compare_lt(v, best)
        if take_lt and less is True:
            best = v
        elif (not take_lt) and less is False and compare_lt(best, v) is True:
            best = v
    return best

"""Turn a Query AST into a sequence of named plan stages."""

from __future__ import annotations

import dataclasses

from microdb.errors import AggregateError
from microdb.expr import has_aggregate
from microdb.parser import OrderItem, Query, SelectItem, Star


@dataclasses.dataclass(frozen=True)
class FromStage:
    table: str
    name: str = "from"


@dataclasses.dataclass(frozen=True)
class JoinStage:
    table: str
    kind: str
    on: object
    name: str = "join"


@dataclasses.dataclass(frozen=True)
class WhereStage:
    pred: object
    name: str = "where"


@dataclasses.dataclass(frozen=True)
class GroupStage:
    keys: tuple[object, ...]
    name: str = "group"


@dataclasses.dataclass(frozen=True)
class HavingStage:
    pred: object
    name: str = "having"


@dataclasses.dataclass(frozen=True)
class SelectStage:
    items: tuple[SelectItem, ...]
    name: str = "select"


@dataclasses.dataclass(frozen=True)
class DistinctStage:
    name: str = "distinct"


@dataclasses.dataclass(frozen=True)
class OrderStage:
    items: tuple[OrderItem, ...]
    name: str = "order"


@dataclasses.dataclass(frozen=True)
class OffsetStage:
    count: int
    name: str = "offset"


@dataclasses.dataclass(frozen=True)
class LimitStage:
    count: int
    name: str = "limit"


@dataclasses.dataclass(frozen=True)
class Plan:
    stages: tuple[object, ...]

    def __len__(self) -> int:
        return len(self.stages)

    def __getitem__(self, index: int) -> object:  # type: ignore[override]
        return self.stages[index]

    def __iter__(self):  # type: ignore[no-untyped-def]
        return iter(self.stages)


def plan(query: Query) -> Plan:
    stages: list[object] = [FromStage(query.from_table)]
    if query.join is not None:
        _forbid_agg(query.join.on, "ON")
        stages.append(JoinStage(query.join.table, query.join.kind, query.join.on))
    if query.where is not None:
        _forbid_agg(query.where, "WHERE")
        stages.append(WhereStage(query.where))
    grouped = bool(query.group_by) or _query_has_agg(query)
    if query.group_by:
        for key in query.group_by:
            _forbid_agg(key, "GROUP BY")
    if grouped:
        stages.append(GroupStage(tuple(query.group_by)))
    if query.having is not None:
        stages.append(HavingStage(query.having))
    stages.append(SelectStage(tuple(query.select_items)))
    if query.distinct:
        stages.append(DistinctStage())
    if query.order_by:
        stages.append(OrderStage(tuple(query.order_by)))
    if query.offset is not None:
        stages.append(OffsetStage(query.offset))
    if query.limit is not None:
        stages.append(LimitStage(query.limit))
    return Plan(tuple(stages))


def _forbid_agg(node: object, clause: str) -> None:
    if has_aggregate(node):
        raise AggregateError(f"aggregate not allowed in {clause}")


def _query_has_agg(query: Query) -> bool:
    for item in query.select_items:
        if isinstance(item.value, Star):
            continue
        if has_aggregate(item.value):
            return True
    if query.having is not None and has_aggregate(query.having):
        return True
    for item in query.order_by:
        if has_aggregate(item.expr):
            return True
    return False

